window.products.push({"id":811374,"name":"Simplify Holiday Light Organizer Box | Holds 500 Lights | Christmas Storage | Tree String Lights | 5 Divider Reels | Collapsible | Ultra Zip | Gold","category":"homeandappliances","retail price":10.01,"sale price":null,"image":"https://m.media-amazon.com/images/I/81LgJQbsy+L._AC_SL1500_.jpg","description":"This Simplify Christmas Light Organizer is a great way to keep your Christmas lights organized and safely stowed away to prevent tangling and damage. Includes handles for easy carrying and a zipper-lid closure for protection from any dirt and debris. See through front allows you to view your lights without having to open and go through the storage unit. Doubled sided zippers on the top and bottom of the unit allows for easy access.","images":["https://m.media-amazon.com/images/I/81LgJQbsy+L._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/61zNIJh6ZCL._SL1500_.jpg","https://m.media-amazon.com/images/I/61TWUez1VxL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51TIpnkrEpL._AC_SL1500_.jpg","https://m.media-amazon.com/images/I/51I6jTu8yCL._AC_SL1300_.jpg","https://m.media-amazon.com/images/I/31o9GyU6jnL._AC_.jpg"],"specifications":{"brand":"Simplify","source_asin":"B083FH4QMN","category_path":"Home & Kitchen"},"sku":"BM-811374","productType":"Home & Appliances","inventory":0,"age_group":"Adult","gender":"Unisex","source_url":"https://www.amazon.com/dp/B083FH4QMN","source_catalog":"Amazon Reviews 2023 product metadata","source_file":"meta_Home_and_Kitchen_2023.jsonl","source_asin":"B083FH4QMN","price_pending":true,"merchant_ready":false});
